/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_paiement_after_delete` 
AFTER DELETE ON `paiement` 
FOR EACH ROW 
BEGIN
    DECLARE facture_count INT DEFAULT 0;
    
    -- Éviter la récursion
    SELECT COUNT(*) INTO facture_count 
    FROM `facture` 
    WHERE `id_facture` = OLD.id_facture 
    FOR UPDATE;
    
    -- Recalculer les totaux pour la facture
    UPDATE `facture` 
    SET 
        `montant_paye_total` = (
            SELECT COALESCE(SUM(montant_paye), 0) 
            FROM `paiement` 
            WHERE `id_facture` = OLD.id_facture 
            AND `statut` = 'confirme'
        ),
        `nb_paiements` = (
            SELECT COUNT(*) 
            FROM `paiement` 
            WHERE `id_facture` = OLD.id_facture 
            AND `statut` = 'confirme'
        ),
        `date_dernier_paiement` = (
            SELECT MAX(date_creation) 
            FROM `paiement` 
            WHERE `id_facture` = OLD.id_facture 
            AND `statut` = 'confirme'
        ),
        `montant_paye` = (
            SELECT montant_paye 
            FROM `paiement` 
            WHERE `id_facture` = OLD.id_facture 
            AND `statut` = 'confirme'
            ORDER BY date_creation DESC 
            LIMIT 1
        )
    WHERE `id_facture` = OLD.id_facture;
    
    -- Recalculer le montant restant et l'état
    UPDATE `facture` 
    SET 
        `montant_restant` = GREATEST(0, `montant_total` - COALESCE(`ristourne`, 0) - COALESCE(`montant_paye_total`, 0)),
        `etat` = CASE 
            WHEN GREATEST(0, `montant_total` - COALESCE(`montant_paye_total`, 0)) <= 0 AND COALESCE(`montant_paye_total`, 0) > 0 THEN 'Payée'
            WHEN COALESCE(`montant_paye_total`, 0) > 0 AND GREATEST(0, `montant_total` - COALESCE(`montant_paye_total`, 0)) > 0 THEN 'Partiellement payée'
            WHEN COALESCE(`montant_paye_total`, 0) = 0 THEN 'Envoyée'
            ELSE `etat`
        END
    WHERE `id_facture` = OLD.id_facture;
END */;;
DELIMITER ;
